begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to anon,authenticated,service_role;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
('80000000-0000-4000-8000-000000000001','sales@phase8.test','{"nome":"Comercial Oito","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}'),
('80000000-0000-4000-8000-000000000002','owner@phase8.test','{"nome":"Dono Oito","tipo":"fornecedor","empresa":"Empresa Oito","cnpj":"11222333000181","telefone":"11999999999","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}');
insert into public.user_roles(user_id,role) values('80000000-0000-4000-8000-000000000001','comercial');
select set_config('test.sid',(select id::text from public.fornecedores where dono_id='80000000-0000-4000-8000-000000000002'),true);
select set_config('test.seg',(select id::text from public.segmentos where slug='elevadores'),true);
insert into public.fornecedor_segmentos(fornecedor_id,segmento_id) values(current_setting('test.sid')::uuid,current_setting('test.seg')::uuid);
update public.fornecedores set status='publicado' where id=current_setting('test.sid')::uuid;
insert into public.contratos(id,fornecedor_id,anunciante_nome,produto,valor_centavos,inicio,fim,status) values
('81000000-0000-4000-8000-000000000001',current_setting('test.sid')::uuid,'Anunciante teste','banner',10000,now()-interval '1 day',now()+interval '30 days','ativo'),
('81000000-0000-4000-8000-000000000002',current_setting('test.sid')::uuid,'Destaque teste','destaque',20000,now()-interval '1 day',now()+interval '30 days','ativo');
insert into public.banners(id,contrato_id,anunciante_nome,posicao_id,imagem_desktop,imagem_mobile,link_destino,inicio,fim,status) select '82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','Anunciante teste',id,'https://example.com/desktop.jpg','https://example.com/mobile.jpg','https://example.com',now()-interval '1 hour',now()+interval '10 days','ativo' from public.banner_posicoes where slug='home_topo';
insert into public.destaques(contrato_id,fornecedor_id,segmento_id,uf,vaga,inicio,fim,status) select '81000000-0000-4000-8000-000000000002',current_setting('test.sid')::uuid,current_setting('test.seg')::uuid,'SP',n,now(),now()+interval '10 days','ativo' from generate_series(1,3)n;
select throws_ok($$insert into public.destaques(contrato_id,fornecedor_id,segmento_id,uf,vaga,inicio,fim,status) values('81000000-0000-4000-8000-000000000002',current_setting('test.sid')::uuid,current_setting('test.seg')::uuid,'SP',1,now()+interval '1 day',now()+interval '5 days','ativo')$$,'23P01',null,'sobreposição rejeitada pela restrição do banco');
select throws_ok($$insert into public.destaques(contrato_id,fornecedor_id,segmento_id,uf,vaga,inicio,fim,status) values('81000000-0000-4000-8000-000000000002',current_setting('test.sid')::uuid,current_setting('test.seg')::uuid,'SP',4,now(),now()+interval '5 days','ativo')$$,'23514',null,'quarta vaga impossível');
select lives_ok($$insert into public.destaques(contrato_id,fornecedor_id,segmento_id,uf,vaga,inicio,fim,status) values('81000000-0000-4000-8000-000000000002',current_setting('test.sid')::uuid,current_setting('test.seg')::uuid,'SP',1,now()+interval '10 days',now()+interval '20 days','ativo')$$,'intervalos adjacentes permitidos');
select lives_ok($$insert into public.destaques(contrato_id,fornecedor_id,segmento_id,uf,vaga,inicio,fim,status) values('81000000-0000-4000-8000-000000000002',current_setting('test.sid')::uuid,current_setting('test.seg')::uuid,'RJ',1,now(),now()+interval '10 days','ativo')$$,'vagas independentes por UF');
select ok(private.highlight_active(current_setting('test.sid')::uuid,'elevadores','SP'),'destaque ativo reconhecido');
select ok(not private.highlight_active(current_setting('test.sid')::uuid,'elevadores','MG'),'destaque não invade outra UF');
set local role anon;
select is(jsonb_array_length(public.banners_publicos('home_topo')),1,'banner ativo público');
select ok(not(public.banners_publicos('home_topo')->0 ? 'contrato_id'),'banner não expõe contrato');
select is(public.destino_banner('82000000-0000-4000-8000-000000000001'),'https://example.com','destino resolve apenas pelo id');
select throws_ok($$select public.comercial_listar('contratos')$$,'42501',null,'visitante sem administração');
select throws_ok($$select * from private.commercial_report_links$$,'42501',null,'tokens privados');
select throws_ok($$select public.registrar_evento_banner(gen_random_uuid(),'82000000-0000-4000-8000-000000000001','impressao',repeat('a',64),true)$$,'42501',null,'público não forja contadores por RPC');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000002',true);
select is((select count(*) from public.contratos),2::bigint,'fornecedor lê contratos próprios');
select throws_ok($$select public.comercial_listar('contratos')$$,'P0001','Acesso comercial negado','fornecedor não administra');
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000001',true);
select is((public.comercial_listar('contratos')->>'total')::int,2,'comercial lista contratos');
select lives_ok($$select public.comercial_salvar('preco',(select id from public.produtos_comerciais where codigo='banner'),'{"preco_centavos":75000,"ativo":true}')$$,'comercial configura preço');
select set_config('test.token',public.link_relatorio('82000000-0000-4000-8000-000000000001')->>'token',true);
select is(length(current_setting('test.token')),64,'token forte de relatório');
reset role;
select ok(not exists(select 1 from private.commercial_report_links where token_hash=current_setting('test.token')),'banco guarda hash, não token');
select set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;
select is(public.registrar_evento_banner('83000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','impressao',repeat('a',64),false)->>'ignorado','true','sem consentimento ignora');
select is(public.registrar_evento_banner('83000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','impressao',repeat('a',64),true)->>'registrado','true','impressão registrada');
select is(public.registrar_evento_banner('83000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','impressao',repeat('a',64),true)->>'duplicado','true','repetição idempotente');
select is(public.registrar_evento_banner('83000000-0000-4000-8000-000000000002','82000000-0000-4000-8000-000000000001','clique',repeat('a',64),true)->>'registrado','true','clique registrado');
reset role;set local role anon;
select is((public.relatorio_anunciante(current_setting('test.token'),current_date-2,current_date+2)->>'impressoes')::int,1,'relatório soma impressão uma vez');
select is((public.relatorio_anunciante(current_setting('test.token'),current_date-2,current_date+2)->>'ctr')::numeric,100::numeric,'CTR calculado');
select ok(not(public.relatorio_anunciante(current_setting('test.token'),current_date-2,current_date+2) ? 'valor_centavos'),'relatório sem financeiro');
select is(public.relatorio_anunciante('invalido',current_date,current_date),null::jsonb,'token inválido sem vazamento');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub','80000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.link_relatorio('82000000-0000-4000-8000-000000000001','revogar')$$,'revogação disponível');
reset role;set local role anon;
select is(public.relatorio_anunciante(current_setting('test.token'),current_date-2,current_date+2),null::jsonb,'revogação imediata');
reset role;
update public.contratos set status='cancelado' where id='81000000-0000-4000-8000-000000000001';
set local role anon;
select is(jsonb_array_length(public.banners_publicos('home_topo')),0,'contrato cancelado retira banner');
select is(public.destino_banner('82000000-0000-4000-8000-000000000001'),null::text,'campanha cancelada sem redirect');
reset role;
update public.contratos set status='ativo' where id='81000000-0000-4000-8000-000000000001';
update public.banners set inicio=now()+interval '1 day',fim=now()+interval '2 days';
set local role anon;
select is(jsonb_array_length(public.banners_publicos('home_topo')),0,'banner futuro não aparece');
reset role;
update public.banners set inicio=now()-interval '20 hours',fim=now()-interval '1 hour';
set local role anon;
select is(jsonb_array_length(public.banners_publicos('home_topo')),0,'banner vencido não aparece');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;
select lives_ok($$select public.alertas_comerciais()$$,'job comercial gera alertas');
select lives_ok($$select public.alertas_comerciais()$$,'job repetido sem erro');
reset role;
select is((select count(*) from public.email_outbox where template='destaque_renovar'),4::bigint,'alertas de destaque em 15 dias sem duplicação');
select * from finish();rollback;
